+	private async runSetup(
+		entry: PluginEntry,
+		generation: number,
+		instance: PluginInstance,
+		invoke: (api: SetupApi) => void | Promise<void>,
+		api: SetupApi,
+		scope: PluginCallScope,
+		input: PluginSessionLoadInput,
+	): Promise<void> {
+		const pending = {
+			tools: [] as AgentTool[],
+			commands: [] as AgentExtensionCommand[],
+			calls: [] as Array<(target: SetupApi) => void>,
+		};
